const DAY_MS = 86400000;

/** Deterministic daily pick: same puzzle for everyone on a given local day. */
export function getDailyPuzzle(date: Date = new Date()): Puzzle {
  const localMidnight = date.getTime() - date.getTimezoneOffset() * 60000;
  const days = Math.floor(localMidnight / DAY_MS);
  const idx = ((days % PUZZLES.length) + PUZZLES.length) % PUZZLES.length;
  return PUZZLES[idx];
}

/** The puzzle's start state (fully revealed, Red to move). */
export function puzzleState(p: Puzzle): JieqiState {
  return parseFen(p.fen);
}
